"use client";

import { useEffect, useState } from "react";
import { Heatmap } from "@paper-design/shaders-react";
import { cn } from "@/lib/utils";

const EMBER = [
  "#1a0b0b",
  "#4a1716",
  "#8f2f2b",
  "#d4615a",
  "#ef8b87",
  "#ffd2c4",
  "#fff6f1",
];

/**
 * Feather the canvas edges so the halo and grain never end in a hard square,
 * which shows on light surfaces. The logo sits well inside the 15% fade band.
 */
const FADE = "linear-gradient(to right, transparent, black 15%, black 85%, transparent)";
const EDGE_FADE = {
  maskImage: `${FADE}, ${FADE.replace("to right", "to bottom")}`,
  maskComposite: "intersect",
  WebkitMaskImage: `${FADE}, ${FADE.replace("to right", "to bottom")}`,
  WebkitMaskComposite: "source-in",
} as const;

export interface HeatmapLogoProps {
  /** Logo image URL or data URI. Only its silhouette is used, so any solid mark works. */
  image: string;
  /** Heat ramp from coolest to hottest, as hex colors. */
  colors?: string[];
  /** Fill behind the logo. Transparent by default, so the glow blends into any surface. */
  background?: string;
  /** Strength of the halo around the logo, 0 to 1. */
  glow?: number;
  className?: string;
}

/** A logo that glows like hot metal, with heat drifting slowly through it. */
export function HeatmapLogo({
  image,
  colors = EMBER,
  background = "#00000000",
  glow = 0.3,
  className,
}: HeatmapLogoProps) {
  const reduceMotion = usePrefersReducedMotion();

  return (
    <div
      aria-hidden="true"
      className={cn("relative aspect-square w-80", className)}
      style={EDGE_FADE}
    >
      <Heatmap
        image={image}
        colors={colors}
        colorBack={background}
        contour={0.45}
        innerGlow={0.55}
        outerGlow={glow}
        noise={0.15}
        angle={0}
        scale={0.62}
        speed={reduceMotion ? 0 : 0.6}
        className="absolute inset-0"
      />
    </div>
  );
}

function usePrefersReducedMotion() {
  const [reduceMotion, setReduceMotion] = useState(false);

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduceMotion(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);

  return reduceMotion;
}
